from wandb.sdk.internal.datastore import DataStore
from wandb.proto import wandb_internal_pb2
import json

run_file = 'wandb/offline-run-20260516_013654-3mt1egu1/run-3mt1egu1.wandb'
ds = DataStore()
ds.open_for_scan(run_file)

count = 0
all_summary = {}
last_history = {}
while True:
    raw = ds.scan_data()
    if raw is None:
        break
    count += 1
    if isinstance(raw, bytes):
        record = wandb_internal_pb2.Record()
        try:
            record.ParseFromString(raw)
            if record.HasField('summary'):
                for item in record.summary.update:
                    if item.value_json:
                        all_summary[item.key] = json.loads(item.value_json)
            if record.HasField('history'):
                for item in record.history.item:
                    if item.value_json:
                        last_history[item.key] = json.loads(item.value_json)
        except Exception as e:
            pass

print('=== WANDB FINAL SUMMARY ===')
for k, v in sorted(all_summary.items()):
    if not k.startswith('_'):
        print(f'{k}: {v}')

print()
print('=== LAST HISTORY ENTRY ===')
for k, v in sorted(last_history.items()):
    if not k.startswith('_'):
        print(f'{k}: {v}')
